import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = nextInt(in);
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt(in);

        // Para cada degrau i, a maior altura possivel em uma reconstrucao valida eh:
        //   ans[i] = min sobre todo degrau conhecido j de (A_j + |i - j|)
        // Pois as restricoes |h_k - h_{k+1}| <= 1 formam um sistema de restricoes de
        // diferenca, e o maximo de h_i dados os valores fixos A_j eh exatamente
        // min_j (A_j + dist(i,j)), com dist(i,j) = |i-j| (grafo em linha).
        // Essa atribuicao eh uma reconstrucao valida (funcao 1-Lipschitz) e respeita
        // os valores conhecidos (a consistencia entre conhecidos eh garantida).

        final long INF = Long.MAX_VALUE / 4;
        long[] ans = new long[n];

        // Passada esquerda->direita: min sobre j <= i de (A_j + (i - j)) = i + min_{j<=i}(A_j - j)
        long best = INF;
        for (int i = 0; i < n; i++) {
            if (a[i] != -1) {
                long v = (long) a[i] - i;
                if (v < best) best = v;
            }
            ans[i] = best + i;
        }

        // Passada direita->esquerda: min sobre j >= i de (A_j + (j - i)) = min_{j>=i}(A_j + j) - i
        best = INF;
        for (int i = n - 1; i >= 0; i--) {
            if (a[i] != -1) {
                long v = (long) a[i] + i;
                if (v < best) best = v;
            }
            long v = best - i;
            if (v < ans[i]) ans[i] = v;
        }

        StringBuilder sb = new StringBuilder(n * 8);
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(ans[i]);
        }
        sb.append('\n');
        System.out.print(sb);
    }

    private static int nextInt(DataInputStream in) throws IOException {
        int ret = 0;
        int b = in.read();
        while (b != -1 && b != '-' && (b < '0' || b > '9')) b = in.read();
        boolean neg = false;
        if (b == '-') { neg = true; b = in.read(); }
        while (b >= '0' && b <= '9') {
            ret = ret * 10 + (b - '0');
            b = in.read();
        }
        return neg ? -ret : ret;
    }
}
